      variant: {
        // Framed at rest; the fills step up on hover and focus like an
        // input field.
        bordered:
          "ring-border bg-transparent hover:bg-muted/50 focus-within:bg-card",
        // Invisible at rest — the InputGroup field ladder: muted fill +
