initial={{
                opacity: 0,
                x: focusRect.left - 2,
                y: focusRect.top - 2,
                width: focusRect.width + 4,
                height: focusRect.height + 4,
              }}

animate={{
                opacity: 1,
                x: focusRect.left - 2,
                y: focusRect.top - 2,
                width: focusRect.width + 4,
                height: focusRect.height + 4,
              }}

