                ...(snap || reduceMotion ? { duration: 0 } : spring.fast),
                opacity: { duration: 0.08 },
              }}

onClick={() => {
          if (!target) return;
          goToMonth(target);
          if (direction === "previous") dayPickerProps.onPrevClick?.(target);
          else dayPickerProps.onNextClick?.(target);
        }}

