declarations.source:
interface CardGroupContextValue {
  registerItem: (index: number, element: HTMLElement | null) => void;
  activeIndex: number | null;
  /** Index of the persistently-selected card, or -1. Its neighbours drop the
   *  hairline that would otherwise cut across the selection fill. */
  selectedIndex: number;
  orientation: CardOrientation;
  columns: number;
  count: number;
  /** Individual cards carry their own border/tile shape (separated grids). */
  separated: boolean;
  /** Inner hairline dividers are drawn between adjacent cards. */
  divided: boolean;
  outlined: boolean;
}

interface CardContextValue {
  emphasized: boolean;
  orientation: CardOrientation;
  clickable: boolean;
  /** An inline card holding a full CardImage centres its text + actions in a
   *  column beside the image, so the footer drops below the text (hugged and
   *  vertically centred) instead of trailing to the right. */
  hasImage: boolean;
}

interface CardGroupProps extends Omit<HTMLAttributes<HTMLDivElement>, "onDrag"> {
  /** How each card lays its own content out.
   *  "card" — stacked vertically (media/header on top). "inline" — a
   *  horizontal row (leading media, trailing footer), like a Table row.
   *  @default "card" */
  orientation?: CardOrientation;
  /** Number of grid columns. >1 enables 2-D fluid hover across rows and columns.
   *  @default 1 */
  columns?: number;
  /** "none" — borderless (default), separated only by subtle dividers.
   *  "outlined" — draws a border: one shared frame when grouped, or one per
   *  card when `separated`. @default "none" */
  border?: CardBorder;
  /** Split the group into individually-shaped cards with a gap between them
   *  (a grid of tiles) instead of one continuous divided block. @default false */
  separated?: boolean;
  /** Enable the magnetic fluid-hover highlight. @default true */
  fluidHover?: boolean;
}

interface CardProps extends Omit<HTMLAttributes<HTMLDivElement>, "onClick"> {
  /** Makes the whole card an interactive target; fluid hover previews it.
   *  Renders a stretched link when `href` is set, else a stretched button. */
  onClick?: () => void;
  href?: string;
  external?: boolean;
  /** Accessible name for the stretched link/button when the whole card is
   *  clickable (the card's visible title isn't wired up automatically). */
  label?: string;
  /** Persistent selected state, on top of the transient fluid hover. */
  selected?: boolean;
  disabled?: boolean;
  /** Shows a dismiss (✕) button in the corner. */
  dismissible?: boolean;
  /** Keep the dismiss control hidden until the card is hovered or holds
   *  focus — the default, so a permanent ✕ never competes with the content.
   *  Pass false for an always-visible control. @default true */
  dismissOnHover?: boolean;
  onDismiss?: () => void;
  /** Pins the card to one step of the size ladder (see /docs/sizes) — compact
   *  tightens type and padding. Omitted, it follows the surrounding
   *  SizeProvider. */
  size?: SizeVariant;
  /** Injected by CardGroup — do not set by hand. */
  index?: number;
}

interface CardMediaProps {
  logo?: CardLogo;
  logoAlt?: string;
  icon?: IconComponent;
  size?: number;
  className?: string;
}

interface CardImageProps {
  src: string;
  alt?: string;
  className?: string;
}

interface CardFeatureProps {
  icon?: IconComponent;
  title: string;
  description?: string;
}

interface CardButtonProps {
  children: React.ReactNode;
  onClick?: () => void;
  href?: string;
  variant?: CardButtonVariant;
  icon?: IconComponent;
  iconPosition?: "start" | "end";
  /** Opens the href in a new tab and appends an outward arrow glyph. */
  external?: boolean;
  disabled?: boolean;
}

interface CarouselDotsAutoplay {
  /** How long each slide plays before the next one, in ms. Default 3000. */
  duration?: number;
  /** Holds the fill where it is, e.g. while the pointer is over the slide. */
  paused?: boolean;
  /** After the last slide, go back to the first. Default true. */
  loop?: boolean;
}

interface CarouselDotsProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "onChange"> {
  /** How many dots to show. */
  count: number;
  /** Index of the current dot. */
  value: number;
  /** Called with the index of a clicked dot, and with the next index each
   *  time autoplay finishes a slide. */
  onValueChange?: (index: number) => void;
  /** Autoplay: the current pill fills over `duration`, then the next slide
   *  comes in. `true` uses the defaults. Omit it for a static, solid pill. */
  autoplay?: boolean | CarouselDotsAutoplay;
  /** Drive the fill yourself, from 0 to 1, when something else owns the
   *  clock. A MotionValue moves it every frame without re-rendering.
   *  Takes precedence over `autoplay`. */
  progress?: number | MotionValue<number>;
  /** Accessible name for each dot. Defaults to "Go to slide N". */
  getLabel?: (index: number) => string;
}

interface ChatMessageProps
  extends Omit<HTMLMotionProps<"div">, "children"> {
  /** Who sent the message. Drives alignment and bubble colour:
   *  `user` → right-aligned accent bubble, `assistant` → left-aligned plain text. */
  from: "user" | "assistant";
  /** Optional attachments rendered as square thumbnails above the bubble. */
  files?: File[];
  /** Side length of each attachment thumbnail in pixels. Defaults to 64. */
  thumbnailSize?: number;
  /** Timestamp shown in the hover-revealed meta row, before the actions.
   *  User-message only — ignored on assistant replies. Caller pre-formats it
   *  (e.g. `"Wednesday 6:08 PM"`). */
  time?: ReactNode;
  /** Icon-only action buttons shown in the hover-revealed meta row (e.g. copy,
   *  edit, regenerate). Rendered next to the timestamp. */
  actions?: ReactNode;
  /** Message body. When omitted the text bubble is dropped (attachment-only message). */
  children?: ReactNode;
  /** Pins the message to one step of the size ladder (see /docs/sizes) —
   *  compact tightens bubble type and padding. Omitted, it follows the
   *  surrounding SizeProvider. */
  size?: SizeVariant;
}

