          // plain checkbox, even inside a label, leaves Enter to submit its
          // form.
          const card = e.currentTarget.closest("[data-slot=field-label]");
          if (e.key === "Enter" && !e.repeat && card?.querySelector(":scope > [data-slot=field]")) {
