export type FluidHoverHighlightProps = (HighlightFromHook | HighlightFromRect) & {
  /** Unused by standard hover (nothing travels). */
  from?: ItemRect | null;
  /** Unused by standard hover (nothing fades). */
  fadeIn?: boolean;
  /** Radius, z-index, anything else. Merged onto
